INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2165790, 296456, 29293, '<td valign="top">move her to a more interesting background</td>', 'move her to a more interesting background', '2006-02-20 13:13:18.000000', NULL, 1),
(2165792, 297671, 29293, '<td valign="top">i like the texture in the background but there is too much of it.  get closer</td>', 'i like the texture in the background but there is too much of it.  get closer', '2006-02-20 13:13:45.000000', NULL, 1),
(2165842, 297025, 12448, '<td valign="top">Ah Don Johnson, I hated him, LOL!  But this looks more like one of the guys Don would have been arresting, LOL!  I like the idea, the shot was well done, the triangle of light on the lense is a bit distracting and the hands don''t seem porportioned for some reason, the one grabbing the wrist looks bigger thean the other one, must be the angle or the way they are set.  A 7</td>', 'Ah Don Johnson, I hated him, LOL!  But this looks more like one of the guys Don would have been arresting, LOL!  I like the idea, the shot was well done, the triangle of light on the lense is a bit distracting and the hands don''t seem porportioned for some reason, the one grabbing the wrist looks bigger thean the other one, must be the angle or the way they are set.  A 7', '2006-02-20 13:29:27.000000', NULL, 1),
(2165845, 297810, 12448, '<td valign="top">Very nice stock shot, clarity, color, light.  Just lacks a touch of emotion for me but otherwise I cannot find fault with this shot.  The negative space on the top is used very well here.  A 9</td>', 'Very nice stock shot, clarity, color, light.  Just lacks a touch of emotion for me but otherwise I cannot find fault with this shot.  The negative space on the top is used very well here.  A 9', '2006-02-20 13:30:15.000000', NULL, 1),
(2165855, 297320, 12448, '<td valign="top">I remember that!  The title is going to hurt you in the end though I think, just a simple, Seoul Olympic Stadium would have been fine.  That alone evokes a ton of memories for me.<br/> <br/>The shot is okay, nothing really jumps out at me and says, LOOK AT ME! and holds my attention.  Seems a bit too dark and slightly, ever so slightly blurred.  A 6</td>', 'I remember that!  The title is going to hurt you in the end though I think, just a simple, Seoul Olympic Stadium would have been fine.  That alone evokes a ton of memories for me. The shot is okay, nothing really jumps out at me and says, LOOK AT ME! and holds my attention.  Seems a bit too dark and slightly, ever so slightly blurred.  A 6', '2006-02-20 13:31:56.000000', NULL, 1),
(2165860, 297139, 12448, '<td valign="top">HAHAHA!  I love the expression!  Just a touch of make up on that boy and this would be close to perfect for the time.  The color of the jacket seems off for some reason, can''t quite place my finger on it but this is a very good overall shot.  The way the light suddenly goes so dark on the right doesn''t quite work for me either, not quite natural for some reason with the face as lighted as it is.  A 7</td>', 'HAHAHA!  I love the expression!  Just a touch of make up on that boy and this would be close to perfect for the time.  The color of the jacket seems off for some reason, can''t quite place my finger on it but this is a very good overall shot.  The way the light suddenly goes so dark on the right doesn''t quite work for me either, not quite natural for some reason with the face as lighted as it is.  A 7', '2006-02-20 13:33:31.000000', NULL, 1),
(2165869, 297412, 12448, '<td valign="top">Okay, the sad part is I don''t recognize any of these name, LOL, but then I''ve always been horrible with names.  I like the idea and the lines leading you in and out is also good but it seems to going in the wrong direction.  Maybe if the they were coming in from the lower left and going out in the upper right?  The light also seems just a tad harsh.  A 6</td>', 'Okay, the sad part is I don''t recognize any of these name, LOL, but then I''ve always been horrible with names.  I like the idea and the lines leading you in and out is also good but it seems to going in the wrong direction.  Maybe if the they were coming in from the lower left and going out in the upper right?  The light also seems just a tad harsh.  A 6', '2006-02-20 13:35:42.000000', NULL, 1),
