(2181219, 297589, 41802, '<td valign="top">Wow I forgot all about this.  Awesome work!</td>', 'Wow I forgot all about this.  Awesome work!', '2006-02-25 01:39:46.000000', NULL, 1),
(2181220, 297636, 41802, '<td valign="top">My mom was just mentioning this the other day when we were talking about the xbox 360.  Great shot.  I love how you took this.</td>', 'My mom was just mentioning this the other day when we were talking about the xbox 360.  Great shot.  I love how you took this.', '2006-02-25 01:41:13.000000', NULL, 1),
