(2185141, 297089, 43774, '<td valign="top">Nice, looks like the 80''s.</td>', 'Nice, looks like the 80''s.', '2006-02-26 20:13:35.000000', NULL, 1),
(2185142, 297666, 43774, '<td valign="top">Pretty flower, water drops are nice.</td>', 'Pretty flower, water drops are nice.', '2006-02-26 20:13:40.000000', NULL, 1),
(2185143, 296330, 43774, '<td valign="top">I love the look of the models (their poses, clothing, makeup, expressions). But I hate the processing you did to give it that pink/yellow solarized look. I would have scored this way higher with a more natural look.</td>', 'I love the look of the models (their poses, clothing, makeup, expressions). But I hate the processing you did to give it that pink/yellow solarized look. I would have scored this way higher with a more natural look.', '2006-02-26 20:13:47.000000', NULL, 1),
