INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2185351, 297822, 23318, '<td valign="top">I''m giving this a 7, rotated about 90 degrees clockwise, I might have given it a higher score. Great idea, and good luck.</td>', 'I''m giving this a 7, rotated about 90 degrees clockwise, I might have given it a higher score. Great idea, and good luck.', '2006-02-26 21:26:12.000000', NULL, 1),
(2185374, 297565, 23318, '<td valign="top">Tossing this a 6. I think your focus point should have been the cubes in his hand. This would have given a clear focus on the reason he used the obvious hammer creating the other pieces. If the guide was then out of focus, I would have relocated it to make it readable.</td>', 'Tossing this a 6. I think your focus point should have been the cubes in his hand. This would have given a clear focus on the reason he used the obvious hammer creating the other pieces. If the guide was then out of focus, I would have relocated it to make it readable.', '2006-02-26 21:35:39.000000', NULL, 1),
(2185513, 297283, 53969, '<td valign="top">I really like this one - it''s fun, as well as being quite well done. The child has a great look in his eye - he looks like he is presenting a challenge to the paccman!!!</td>', 'I really like this one - it''s fun, as well as being quite well done. The child has a great look in his eye - he looks like he is presenting a challenge to the paccman!!!', '2006-02-26 22:48:23.000000', NULL, 1),
(2185723, 297788, 37893, '<td valign="top">Shhesh! I remember having HUGE hair! Yep definitely Flock of Seagulls style ;) Great image. The water is nicely rendered. Seems like a bit of NI here but thats cool. Still a good score from me. 9</td>', 'Shhesh! I remember having HUGE hair! Yep definitely Flock of Seagulls style ;) Great image. The water is nicely rendered. Seems like a bit of NI here but thats cool. Still a good score from me. 9', '2006-02-26 23:56:35.000000', NULL, 1),
(2185744, 296930, 772, '<td valign="top">I think there is a retard in the mix of your comments... :)</td>', 'I think there is a retard in the mix of your comments... :)', '2006-02-27 00:06:20.000000', NULL, 0),
(2185746, 295129, 47852, '<td valign="top">Fantastic job... I gave this one a ten.  Couldn''t wait to come back to see how it was done.  Thanks for taking the time to write up your description for us!  Well done! :)</td>', 'Fantastic job... I gave this one a ten.  Couldn''t wait to come back to see how it was done.  Thanks for taking the time to write up your description for us!  Well done! :)', '2006-02-27 00:06:48.000000', NULL, 0),
(2185748, 296930, 93, '<td valign="top">Wrong decade. <br/> <br/>DPCers apparently all suffer from the same memory warp though.</td>', 'Wrong decade.  DPCers apparently all suffer from the same memory warp though.', '2006-02-27 00:07:15.000000', NULL, 0),
